package org.apache.commons.math3.optimization.linear;

import org.apache.commons.math3.linear.Array2DRowRealMatrix;
import org.apache.commons.math3.linear.MatrixUtils;
import org.apache.commons.math3.linear.RealVector;
import org.apache.commons.math3.optimization.GoalType;
import org.apache.commons.math3.optimization.linear.LinearConstraint;
import org.apache.commons.math3.optimization.linear.LinearObjectiveFunction;
import org.apache.commons.math3.optimization.linear.Relationship;
import org.junit.Test;
import static org.junit.Assert.*;

import java.util.ArrayList;
import java.util.Collection;

public class AgentBRT_Math_33_ast_edit_Test {

    @Test
    public void testReproduceBug() {
        // Define the linear objective function
        LinearObjectiveFunction f = new LinearObjectiveFunction(new double[] {1, 0.5}, 0);

        // Define the constraints
        Collection<LinearConstraint> constraints = new ArrayList<>();
        constraints.add(new LinearConstraint(new double[] {0, 0.5}, Relationship.LEQ, 2));
        constraints.add(new LinearConstraint(new double[] {0, 0}, Relationship.LEQ, 3));

        // Create the SimplexTableau
        SimplexTableau tableau = new SimplexTableau(f, constraints, GoalType.MAXIMIZE, false, 0.0001);

        // Invoke the method that should drop phase 1 objective
        tableau.dropPhase1Objective();

        // Check the resulting tableau dimensions
        // Expecting the first row to be removed and the last column to be dropped
        assertEquals(2, tableau.getHeight());
        assertEquals(3, tableau.getWidth());
    }
}

