public class AgentBRT_Math_33_ast_edit_Test {

    @Test
    public void testReproduceBug() {
        // Setup a tableau with specific entries
        double[][] data = {
            {1.0, 0.5, 0.0, 0.0, 1.0},
            {0.0, 0.5, 1.0, 0.0, 2.0},
            {0.0, 0.0, 0.0, 1.0, 3.0}
        };
        RealMatrix matrix = new Array2DRowRealMatrix(data);
        SimplexTableau tableau = new SimplexTableau(matrix, null, null, false, 0.0001);

        // Invoke the method that should drop phase 1 objective
        tableau.dropPhase1Objective();

        // Check the resulting tableau dimensions
        // Expecting the first row to be removed and the last column to be dropped
        assertEquals(2, tableau.getHeight());
        assertEquals(4, tableau.getWidth());
    }
}

